TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"## Question 1"},{"id":"R2","met":"yes","where":"## Question 2"},{"id":"R3","met":"partial","where":"## Question 3"},{"id":"R4","met":"partial","where":"## Question 4"},{"id":"R5","met":"partial","where":"## Question 5"},{"id":"R6","met":"partial","where":"## Question 6"},{"id":"R7","met":"partial","where":"## References"}],"technical_issues":[{"where":"## Question 1","issue":"The response measure for the availability scenario ('stay up most of the time') is qualitative and not measurable."},{"where":"## Question 3","issue":"Arithmetic calculation error in part (b): 0.00699 × 720 hours equals 5.03 hours, not 3.5 hours."},{"where":"## Question 3","issue":"In part (c), end-to-end order placement availability was calculated using only the payment subsystem (99.9975%), omitting the other three series components."},{"where":"## Question 4","issue":"Circuit breaker states are inverted: normal requests pass through when Closed, and requests fail immediately when Open."},{"where":"## Question 4","issue":"No drawback or tuning consideration is stated for the Circuit Breaker pattern."},{"where":"## Question 5","issue":"The CAP theorem explanation incorrectly states that partition tolerance can be sacrificed to achieve consistency and availability during a network partition."},{"where":"## Question 5","issue":"No concrete technique is proposed for placing and paying for an order."},{"where":"## Question 6","issue":"The ADR lists only positive consequences; negative consequences or operational trade-offs are omitted."},{"where":"## References","issue":"Citation [2] is referenced in Question 4 but omitted from the reference list."}],"overall":"The submission demonstrates strong architectural rationale in Question 2 and good ADR formatting in Question 6. However, marks were lost due to calculation errors in Question 3, inverted circuit breaker states in Question 4, an incomplete CAP response in Question 5, and minor formatting/word-count infractions.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are appropriate and justified from the scenario. The performance scenario is complete with a measurable metric. However, the availability scenario's response measure ('stay up most of the time') is qualitative and non-measurable.","evidence":[{"where":"## Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"A modular monolith is clearly recommended and justified using scenario-specific trade-offs: team size (5 developers) versus operational overhead, and addressing single-VM and deployment downtime. Trade-offs and downsides (shared failure domain, lack of independent scaling) are acknowledged.","evidence":[{"where":"## Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."}]},{"id":"C3","level":"Developing","mark":4.0,"scale":8.0,"points":4.0,"max":8.0,"reasoning":"Part (a) is correct (99.30%). In part (b), an arithmetic error occurs: 0.00699 × 720 equals 5.03 hours, not 3.5. In part (c), the student omitted the other series components, equating overall availability solely to the parallel payment provider availability.","evidence":[{"where":"## Question 3","quote":"So the new availability of placing an order is 99.9975%, which reduces the downtime to 0.000025 × 720 = 0.018 hours"}]},{"id":"C4","level":"Developing","mark":2.0,"scale":5.0,"points":2.0,"max":5.0,"reasoning":"Although the Circuit Breaker is an appropriate pattern and applied to the outage, the explanation inverts the state machine (stating calls pass through when Open and fail fast when Closed). Furthermore, no drawback or tuning consideration is provided.","evidence":[{"where":"## Question 4","quote":"In the Open state calls pass through normally."}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Both trade-off choices are sound, and Redis caching is properly suggested for menu browsing. However, no concrete technique is given for order placement/payment, and CAP is misconstrued by stating partition tolerance can be traded off during a network partition.","evidence":[{"where":"## Question 5","quote":"so for payments we choose consistency and availability and give up partition tolerance."}]},{"id":"C6","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Context and Decision are clear, well reasoned, and specific to the scenario. However, the Consequences section is strictly one-sided, omitting any negative consequences or architectural trade-offs (such as message broker maintenance or eventual consistency handling).","evidence":[{"where":"## Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"The submission uses required headings and clear language. However, Question 2 exceeds the 150-word limit (~188 words), and citation [2] referenced in Question 4 is missing from the reference list.","evidence":[{"where":"## Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."}]}]}
